+pub fn save(config_dir: &Path, session: &mut Session) -> anyhow::Result<PathBuf> {
+    // Advance on a candidate clone and publish it back to the caller only after
+    // the durable rename succeeds. A failed write therefore changes neither
+    // the in-memory nor the last-good on-disk revision.
+    let mut candidate = session.clone();
+    candidate.persistence_revision = candidate
+        .persistence_revision
+        .checked_add(1)
+        .context("session persistence revision exhausted")?;
+    let dir = match candidate.workspace_root.as_deref() {
         Some(root) => workspace_dir(config_dir, root),
         None => sessions_dir(config_dir).join("legacy"),
     };
     std::fs::create_dir_all(&dir).with_context(|| format!("mkdir {}", dir.display()))?;
-    let path = dir.join(format!("{}.json", session.id));
-    let json = serde_json::to_string_pretty(session)?;
+    let path = dir.join(format!("{}.json", candidate.id));
+    let json = serde_json::to_string_pretty(&candidate)?;
     // Atomic + durable write: a crash mid-write must never corrupt an
     // existing good transcript. Write to a temp sibling, fsync it, then
     // rename over the target.
