+/// Origin rail for a session-projection frame.
+#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
+#[serde(rename_all = "snake_case")]
+pub enum SessionProjectionSource {
+    Agent,
+    Control,
+    Checkpoint,
+}
+
+/// One ordered, session-scoped projection frame. Agent/control events retain
+/// their existing wire shape. Checkpoint events decode as
+/// [`SessionProjectionCheckpoint`]. Snapshot `pending_events` are reduced in
+/// cursor order only for transcript/tool/checkpoint content; folded state is
+/// installed separately and must not also be reduced from these frames.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
+pub struct SessionProjectionFrame {
+    pub cursor: String,
+    pub source: SessionProjectionSource,
+    pub event: Value,
+}
+
+/// Authoritative folded replacements not fully represented by provider history.
+/// After hydrating session content and reducing `pending_events`, clients install
+/// every field here as the final active/terminal/reroute/permission/component/
+/// browser value. These fields are not reducer inputs, which prevents duplicate
+/// application of the same pending frame.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
