        assert_eq!(
            store
                .page_after(&wrong_session, &snapshot.cursor, &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::WrongSession
        );
        let future = ProjectionCursor::new(&store.epoch, &session, 2).to_string();
        assert_eq!(
            store
                .page_after(&session, &future, &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::Future
        );
    }

    #[test]
    fn subscribe_before_page_catches_append_and_pages_durable_row() {
        let store = store(DEFAULT_LEASE);
