    #[test]
    fn visible_checkpoint_replaces_failed_partial_and_preserves_folded_state() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let failed_turn = AgentTurnId::new_v4();
        let next_turn = AgentTurnId::new_v4();
        let attached = attach(&store, &session.to_string(), 0);
        store
            .append_agent(&AgentTurnEvent::TurnStarted {
                session_id: session,
                turn_id: failed_turn,
                model: Some("primary".into()),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: session,
                turn_id: failed_turn,
                delta: "partial that was never persisted".into(),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::ModelRerouted {
                session_id: session,
                turn_id: failed_turn,
                requested: "primary".into(),
                effective: "fallback".into(),
                reason: "pre-stream failure".into(),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::TurnFinished {
                session_id: session,
                turn_id: failed_turn,
                status: ocean_agent_sdk::AgentTurnStatus::Failed,
                error: Some("provider failed".into()),
                wall_ms: Some(1),
                output_tokens: None,
                input_tokens: None,
                cache_read_tokens: None,
                tokens_per_second: None,
                context_usage: None,
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::TurnStarted {
                session_id: session,
                turn_id: next_turn,
                model: Some("fallback".into()),
            })
            .unwrap();
        let durable = serde_json::json!({
            "type": "projection_checkpoint",
            "persistence_revision": 1,
            "transcript": [{"role":"user","text":"accepted next prompt"}],
            "tool_context": [],
        });
        store
            .checkpoint(&session.to_string(), 1, durable.clone())
            .unwrap();

        let live = store
            .page_after(&session.to_string(), &attached.cursor, &attached.lease_id)
            .unwrap();
        assert!(live
            .iter()
            .any(|frame| { frame.event["delta"] == "partial that was never persisted" }));
        let replacement = live.last().unwrap();
        assert_eq!(replacement.source, SessionProjectionSource::Checkpoint);
        assert_eq!(replacement.event, durable);

        let fresh = attach(&store, &session.to_string(), 1);
        let replacement_checkpoint: SessionProjectionCheckpoint =
            serde_json::from_value(replacement.event.clone()).unwrap();
        assert_eq!(fresh.checkpoint, Some(replacement_checkpoint));
        assert!(fresh.pending_events.is_empty());
        assert!(fresh.state.active_turn.is_some());
        assert!(fresh.state.last_turn_finished.is_some());
        assert_eq!(
            fresh.state.model_rerouted.as_ref().unwrap()["effective"],
            "fallback"
        );
    }

    #[test]
    fn cancellation_is_journaled_and_clears_pending_permissions() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let attached = attach(&store, &session.to_string(), 0);
        let permission_id = ocean_core::PermissionId::new_v4();
        let mut request = EventEnvelope::new(OceanEvent::PermissionRequest {
            tool: "bash".into(),
            reason: "approval".into(),
            args: serde_json::json!({}),
        });
        request.session_id = Some(session.0);
        request.permission_id = Some(permission_id);
        store.append_control(&request).unwrap();
        let mut cancelled = EventEnvelope::new(OceanEvent::Cancelled {
            reason: Some("operator cancelled".into()),
        });
        cancelled.session_id = Some(session.0);
        store.append_control(&cancelled).unwrap();

        let fresh = attach(&store, &session.to_string(), 0);
        assert!(fresh.state.pending_permissions.is_empty());
        let page = store
            .page_after(&session.to_string(), &attached.cursor, &attached.lease_id)
            .unwrap();
        assert_eq!(page.len(), 2);
        assert_eq!(page[1].source, SessionProjectionSource::Control);
        let encoded = serde_json::to_string(&page[1].event).unwrap();
        assert!(encoded.contains("cancelled"));
        assert!(encoded.contains("operator cancelled"));
    }

    #[test]
    fn identified_leases_are_bounded_renewed_and_session_scoped() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4().to_string();
        let other = AgentSessionId::new_v4().to_string();
        let first = store.issue_lease(&session, 0).0;
        for _ in 1..=MAX_LEASES {
            store.issue_lease(&session, 0);
        }
        assert_eq!(
            store.validate_lease(&session, &first, 0).unwrap_err(),
            ProjectionReset::InvalidLease
        );
        assert_eq!(
            store
                .validate_lease(&other, &store.issue_lease(&session, 0).0, 0)
                .unwrap_err(),
            ProjectionReset::LeaseSessionMismatch
        );
        let lease = store.issue_lease(&session, 0).0;
        store.acknowledge_lease(&lease, 3).unwrap();
        assert_eq!(
            store.validate_lease(&session, &lease, 2).unwrap_err(),
            ProjectionReset::InvalidLease
        );
        store.validate_lease(&session, &lease, 3).unwrap();
    }

    #[test]
    fn tail_queries_renew_identified_lease_and_expiry_resets() {
        let store = store(Duration::from_millis(200));
        assert_eq!(store.connection_lifetime(), Duration::from_millis(100));
        let session = AgentSessionId::new_v4().to_string();
        let attached = attach(&store, &session, 0);
        store
            .begin_tail_request(&session, &attached.cursor, &attached.lease_id)
            .unwrap();
        std::thread::sleep(Duration::from_millis(75));
        assert!(store
            .page_after(&session, &attached.cursor, &attached.lease_id)
            .unwrap()
            .is_empty());
        std::thread::sleep(Duration::from_millis(75));
        assert!(store
            .page_after(&session, &attached.cursor, &attached.lease_id)
            .unwrap()
            .is_empty());
        std::thread::sleep(Duration::from_millis(250));
        assert_eq!(
            store
                .page_after(&session, &attached.cursor, &attached.lease_id)
                .unwrap_err(),
            ProjectionReset::ExpiredLease
        );
    }

