    fn oversized_checkpoint_uses_refetch_marker_without_faulting() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4().to_string();
        let attached = attach(&store, &session, 0);
        let huge_text = "x".repeat(MAX_CHECKPOINT_BYTES + 1024);
        let oversized = serde_json::json!({
            "type": "projection_checkpoint",
            "persistence_revision": 1,
            "transcript": [{"role":"assistant","text": huge_text}],
            "tool_context": [],
        });
        store.checkpoint(&session, 1, oversized.clone()).unwrap();
        let live = store
            .page_after(&session, &attached.cursor, &attached.lease_id)
            .unwrap();
        let marker: SessionProjectionCheckpoint =
            serde_json::from_value(live.last().unwrap().event.clone()).unwrap();
        assert_eq!(
            marker,
            SessionProjectionCheckpoint::Refetch {
                persistence_revision: 1
            }
        );

        let fresh = store.snapshot(&session, 1, oversized).unwrap();
        assert_eq!(fresh.checkpoint, Some(marker));
        assert!(fresh.pending_events.is_empty());
        store
            .begin_tail_request(&session, &fresh.cursor, &fresh.lease_id)
            .unwrap();
        assert!(store
            .page_after(&session, &fresh.cursor, &fresh.lease_id)
            .unwrap()
            .is_empty());
        assert!(!store.is_faulted(&session));
    }

