            session::save(&self.config_dir, &mut session)?;
            if let Some(sink) = event_sink.as_ref() {
                let _ = sink.send(AgentEvent::PersistenceCheckpoint {
                    session_id: Some(session_id.to_string()),
                    persistence_revision: session.persistence_revision,
                    snapshot: session::projection_checkpoint(&session),
                });
            }
        }

