            if !res.stdout.trim().is_empty() {
                emit_with_origin(
                    &state.events,
                    res.session_id,
                    Some(request_id),
                    None,
                    origin,
                    OceanEvent::AssistantDelta {
                        text: res.stdout.clone(),
                    },
