    }
}

fn render_tool_output(content: &[ocean_protocol::Content]) -> String {
    use ocean_protocol::Content;
    let mut out = String::new();
    for c in content {
        match c {
            Content::Text { text } => {
                if !out.is_empty() {
                    out.push('\n');
                }
                out.push_str(text);
            }
            Content::Thinking { thinking, .. } => {
                if !out.is_empty() {
                    out.push('\n');
                }
                out.push_str(thinking);
            }
            Content::Image { .. } => {}
            Content::ToolCall {
                name, arguments, ..
            } => {
                if !out.is_empty() {
                    out.push('\n');
                }
                out.push_str(&format!("→ {name}({arguments})"));
            }
        }
    }
    out
}

